        function writeReservations(list, reservations) {
            list.innerHTML = "";
            let status = {
                type: "",
                class: "",
                text: ""
            };
            reservations.forEach((reservation => {
                if (reservation.type != "close") {
                    console.log(reservation);
                    switch (reservation.type) {
                      case "new":
                        status.type = "new";
                        status.class = "new-reservation";
                        status.text = "Заявка";
                        break;

                      case "waiting":
                        status.type = "waiting";
                        status.class = "waiting-reservation";
                        status.text = "Ожидание";
                        break;

                      case "come":
                        status.type = "come";
                        status.class = "open-reservation";
                        status.text = "Открыто";
                        break;
                    }
                    if (status.type == "come") {
                        const currentTime = new Date;
                        const endReserv = new Date(reservation["end_reservation"]);
                        const diffMillis = endReserv.getTime() - currentTime.getTime();
                        const diffMinutes = diffMillis / 1e3 / 60;
                        if (diffMinutes > 0) {
                            const isWithin15Minutes = 15 >= diffMinutes;
                            if (isWithin15Minutes) {
                                status.class = "expiring-reservation";
                                status.text = "Осталось меньше 15 минут";
                            }
                        } else {
                            status.class = "expired-reservation";
                            status.text = "Время вышло";
                        }
                    }
                    let endReserv = new Date(reservation["end_reservation"]);
                    let startReserv = new Date(reservation["start_reservation"]);
                    list.insertAdjacentHTML("beforeEnd", `\n\t\t<li class="list-page-1__li ">\n\t\t\t<button class="li-list-page-1 ${status.class}" data-reserv="${reservation.id}">\n\t\t\t\t<div class="li-list-page-1__top">\n\t\t\t\t\t<p class="li-list-page-1__number">№${reservation.id}</p>\n\t\t\t\t\t<p class="li-list-page-1__table">Стол №${reservation.id_table}</p>\n\t\t\t\t</div>\n\t\t\t\t<div class="li-list-page-1__middle">\n\t\t\t\t\t<p class="li-list-page-1__name-amount">${reservation.name}, ${reservation.amount_guests} чел.</p>\n\t\t\t\t\t<p class="li-list-page-1__time">С ${startReserv.getHours().toString().padStart(2, "0")}:${startReserv.getMinutes().toString().padStart(2, "0")} до ${endReserv.getHours().toString().padStart(2, "0")}:${endReserv.getMinutes().toString().padStart(2, "0")}</p>\n\t\t\t\t</div>\n\t\t\t\t<div class="li-list-page-1__bottom">\n\t\t\t\t\t<p class="li-list-page-1__status">${status.text}</p>\n\t\t\t\t</div>\n\t\t\t</button>\n\t\t</li>`);
                }
            }));
        }
